public class Main {
  public static void main(String[] args) {
    int res = Sh(new int[] {1, 2, 6, 5, 4}, 4);
    System.out.println(res);
  }

  static int Sh(int[] a, int x) {
    if (a.length == 0) {
      return 0;
    }
    if (a[a.length - 1] < x) {
      return a.length;
    }
    int i = 0;
    int j = a.length;
    while (i + 1 < j) {
      int m = i + (j - i) / 2;
      if (a[m] >= x) {
        j = m;
      } else {
        i = m;
      }
    }
    if (a[i] >= x) {
      return i;
    } else {
      return j;
    }
  }
}
